/**
 * Unit tests for CategoryPlot.getRangeAxisIndex
 */
public class CategoryPlot_getRangeAxisIndex_TriageGen1Test {

    private CategoryPlot categoryPlot;

    @Before
    public void setUp() {
        categoryPlot = new CategoryPlot();
    }

    /**
     * Test case where the axis is found directly in the CategoryPlot's range axes list.
     * This covers the branch where result >= 0.
     */
    @Test
    public void testGetRangeAxisIndex_FoundInLocalAxes() {
        ValueAxis axis = mock(ValueAxis.class);
        categoryPlot.setRangeAxis(axis); // Index 0

        int index = categoryPlot.getRangeAxisIndex(axis);

        assertEquals("Should return the correct index from local range axes", 0, index);
    }

    /**
     * Test case where the axis is NOT in the CategoryPlot, but the parent is a CategoryPlot
     * and the axis is found in the parent.
     * This covers the branch: result < 0 AND parent instanceof CategoryPlot AND parent.getRangeAxisIndex(axis) >= 0.
     */
    @Test
    public void testGetRangeAxisIndex_FoundInParentCategoryPlot() {
        // Create a mock CategoryPlot to act as parent
        CategoryPlot parentPlot = mock(CategoryPlot.class);
        ValueAxis axis = mock(ValueAxis.class);

        // Mock the getParent call via a spy or by setting it if possible. 
        // Since getParent is likely a protected/public method from Plot, 
        // and we cannot easily mock the internal 'parent' field of a real object without reflection,
        // we use a subclass to inject the parent for testing purposes.
        CategoryPlot childPlot = new CategoryPlot() {
            @Override
            public Plot getParent() {
                return parentPlot;
            }
        };

        // Setup parent behavior
        when(parentPlot.getRangeAxisIndex(axis)).thenReturn(2);

        int index = childPlot.getRangeAxisIndex(axis);

        assertEquals("Should delegate to parent CategoryPlot if not found locally", 2, index);
    }

    /**
     * Test case where the axis is NOT in the CategoryPlot, and the parent is NOT a CategoryPlot.
     * This covers the branch: result < 0 AND parent is NOT an instance of CategoryPlot.
     */
    @Test
    public void testGetRangeAxisIndex_ParentIsNotCategoryPlot() {
        Plot nonCategoryParent = mock(Plot.class);
        ValueAxis axis = mock(ValueAxis.class);

        CategoryPlot childPlot = new CategoryPlot() {
            @Override
            public Plot getParent() {
                return nonCategoryParent;
            }
        };

        int index = childPlot.getRangeAxisIndex(axis);

        assertEquals("Should return -1 if not found locally and parent is not CategoryPlot", -1, index);
    }

    /**
     * Test case where the axis is NOT in the CategoryPlot, the parent IS a CategoryPlot,
     * but the axis is also NOT in the parent.
     * This covers the branch: result < 0 AND parent instanceof CategoryPlot AND parent.getRangeAxisIndex(axis) < 0.
     */
    @Test
    public void testGetRangeAxisIndex_NotFoundInParentCategoryPlot() {
        CategoryPlot parentPlot = mock(CategoryPlot.class);
        ValueAxis axis = mock(ValueAxis.class);

        CategoryPlot childPlot = new CategoryPlot() {
            @Override
            public Plot getParent() {
                return parentPlot;
            }
        };

        when(parentPlot.getRangeAxisIndex(axis)).thenReturn(-1);

        int index = childPlot.getRangeAxisIndex(axis);

        assertEquals("Should return -1 if not found in local and not found in parent", -1, index);
    }
}
